create or replace view public.pending_mandates_with_beneficiaries as
 SELECT m.id, m.reference, m.insurance_org_id, m.created_by_user_id, m.beneficiary_id, m.customer_category, m.mandate_type, m.remuneration_mode, m.title, m.description, m.sinister_type, m.priority, m.status, m.visible_on_map, m.secondary_contact_first_name, m.secondary_contact_last_name, m.secondary_contact_mobile, m.secondary_contact_phone, m.secondary_contact_role, m.preferred_date, m.preferred_time, m.address_line_1, m.address_line_2, m.postal_code, m.city, m.country, m.latitude, m.longitude, m.location_type, m.residence_type, m.floor, m.entry_code, m.affected_rooms, m.affected_surfaces, m.defect_type, m.damaged_goods_value, m.covering_type, m.appliance_type, m.installation_type, m.prerequisites, m.sms_alert_enabled, m.network_available, m.comments, m.symptoms, m.incident_date, m.drop_at, m.expiry_at, m.assigned_at, m.closed_at, m.redrop_count, m.internal_notes, m.created_at, m.updated_at, m.scheduled_date, m.scheduled_time_slot, m.scheduled_date_2, m.scheduled_date_3, m.workflow_stage, m.assigned_expert_id,
    b.id AS beneficiary_id_full, b.organization_id AS beneficiary_organization_id, b.first_name AS beneficiary_first_name, b.last_name AS beneficiary_last_name, b.mobile_phone AS beneficiary_mobile_phone, b.landline_phone AS beneficiary_landline_phone, b.email AS beneficiary_email, b.created_at AS beneficiary_created_at, b.updated_at AS beneficiary_updated_at,
    m.slot_1_at, m.slot_2_at, m.slot_3_at
   FROM mandates m
     LEFT JOIN beneficiaries b ON m.beneficiary_id = b.id
  WHERE m.workflow_stage = 'pending'::workflow_stage;
